@media (max-width:640px){
  /* Widen, don't shorten (Jonathan 2026-10-12): on a phone the clue takes the band's full width, with the arrow and
     the order beneath it; each finding takes the full width, with its arrow and meaning on the next line. */
  .w5a .w5b{grid-template-columns:20px minmax(0,1fr);row-gap:4px}
  .w5a .w5c{font-size:14.5px;grid-column:1/-1;padding-right:0}
  .w5a .w5ar{align-self:start;margin-top:2px}
  .w5a .w5o{font-size:16px}
  .w5a .w5f{grid-template-columns:20px minmax(0,1fr)}
  .w5a .w5fd{font-size:12.5px;grid-column:1/-1;padding-bottom:2px}
  .w5a .w5fd.fl{padding-bottom:2px}
  .w5a .w5fd.fl::before,.w5a .w5fd.fl.f1::before{bottom:0;height:auto}
  .w5a .w5fd > .ld{display:none}
  .w5a .w5an{grid-column:1;background:linear-gradient(rgba(84,74,196,.42),rgba(84,74,196,.42)) 2px 0/1.5px 100% no-repeat}
  .w5a .w5an.fl{background-size:1.5px 12px}
  .w5a .w5an::before,.w5a .w5an.f1::before{left:2px;right:4px;top:11.5px}
  .w5a .w5an::after,.w5a .w5an.f1::after{right:5px;top:8px}
  .w5a .w5m,.w5a .w5m.f1{grid-column:2;max-width:none;padding-top:2px}
  /* Same rule for the label-and-text notes (.pearls): the label sits above its text on a phone. The 980 px rule
     already sets one column, but dd kept grid-column 2, which made an implicit narrow second column. */
  .pearls .rows:not(.mnem) > dt,.pearls .rows:not(.mnem) > dd{grid-column:1}
}
